--region lifecycle
function CardProgressionEquipmentEngraveNode:__init()
end

function CardProgressionEquipmentEngraveNode:__delete()
end

function CardProgressionEquipmentEngraveNode:Awake()
end

function CardProgressionEquipmentEngraveNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
