--region public
---初始化节点
---@param equipDojo EquipDojo
function CardProgressionEquipmentEngraveNode:RefreshNode(equipDojo)
    local bindPlayerCardId = checkNumber(equipDojo.bindPlayerCardId)
    if bindPlayerCardId <= 0 then return end

    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(bindPlayerCardId)
    local cardSkin = cardDojo.cardSkin
    ---@type CardSkinVo
    local skinVo = cardConfMgr:GetCardSkinBySkinId(cardSkin)
    CfUtils.FillImage(self.ImgRoleHead, skinVo.buffHead)

    local playerCardId = checkInt(equipDojo.playerCardId)
    local grayGraphics = self.ImgRoleHead:GetComponent(typeof(UIGrayGraphics))
    if isNull(grayGraphics) then return end
    
    local isGary = playerCardId ~= bindPlayerCardId
    grayGraphics:MarkGray(isGary)
    CfUtils.SetUISwitchImage(self.ImgBg, isGary and 1 or 2)
end
--endregion public



return CardProgressionEquipmentEngraveNode